    private static function stage_for_level($level){$level=strtolower(trim((string)$level));if(str_contains($level,'intro')||str_contains($level,'beginner'))return array('key'=>'foundation','label'=>'Foundation','rank'=>10);if(str_contains($level,'intermediate')||str_contains($level,'undergraduate'))return array('key'=>'development','label'=>'Development','rank'=>20);if(str_contains($level,'professional')||str_contains($level,'advanced'))return array('key'=>'applied','label'=>'Applied / advanced','rank'=>30);return array('key'=>'unspecified','label'=>'Level not sequenced','rank'=>40);}
    private static function access_score($access,$pref){$access=sanitize_key((string)$access);$open=array('free-open','free-course','free-certificate');$free=array_merge($open,array('free-audit','free-preview'));if('open-first'===$pref){if(in_array($access,$open,true))return 12;if(in_array($access,$free,true))return 4;return -8;}if('free-any'===$pref)return in_array($access,$free,true)?8:-8;return 0;}
