    public static function build_plan($args=array(),$uid=0){
        $topic=self::clean($args['topic']??$args['q']??'',180);$goal=self::clean_area($args['goal']??'',600);$pathway=sanitize_key((string)($args['pathway']??''));$access=sanitize_key((string)($args['access']??'open-first'));if(!isset(self::ACCESS_PREFERENCES[$access]))$access='open-first';$limit=min(6,max(1,absint($args['limit']??4)));$pathways=self::pathways();if($pathway&&!isset($pathways[$pathway]))$pathway='';$tokens=self::tokenize(trim($topic.' '.$goal));$learning=self::course_plan($uid);$providers=self::providers();$ranked=array();
        foreach(self::catalog() as $c){$id=sanitize_key((string)($c['id']??''));if(!$id||!self::access_allowed($c['access']??'',$access))continue;$hay=strtolower(implode(' ',array_merge(array((string)($c['title']??''),(string)($c['institution']??''),(string)($c['summary']??''),(string)($c['level']??''),(string)($c['prerequisites']??'')),(array)($c['subjects']??array()))));$score=self::access_score($c['access']??'',$access);$reasons=array();$matched=array();foreach($tokens as $t){if(str_contains($hay,$t)){$score+=str_contains(strtolower((string)($c['title']??'')),$t)?10:4;$matched[]=$t;}}$cp=array_values(array_filter(array_map('sanitize_key',(array)($c['pathways']??array()))));if($pathway&&in_array($pathway,$cp,true)){$score+=28;$reasons[]='selected-knowledge-pathway';}if(!$pathway&&$tokens){foreach($cp as $slug){$terms=strtolower((string)($pathways[$slug]['terms']??''));foreach($tokens as $t){if($terms&&str_contains($terms,$t))$score+=2;}}}if($matched)$reasons[]='course-metadata-match:'.implode(',',array_slice(array_unique($matched),0,5));if(!$tokens&&!$pathway){$score+=1;$reasons[]='general-learning-catalog';}if($score<1)continue;$stage=self::stage_for_level($c['level']??'');$pid=sanitize_key((string)($c['provider']??''));$p=$providers[$pid]??array();$ranked[]=array('course_id'=>$id,'title'=>self::clean($c['title']??'',240),'institution'=>self::clean($c['institution']??'',160),'provider'=>self::clean($p['name']??$pid,160),'url'=>esc_url_raw((string)($c['url']??'')),'subjects'=>array_values(array_map(static fn($v)=>self::clean($v,80),(array)($c['subjects']??array()))),'level'=>self::clean($c['level']??'',80),'stage'=>$stage['key'],'stage_label'=>$stage['label'],'stage_rank'=>$stage['rank'],'access'=>sanitize_key((string)($c['access']??'')),'access_label'=>self::clean($c['access_label']??'',100),'access_note'=>self::clean_area($c['access_note']??'',600),'duration_label'=>self::clean($c['duration_label']??'',100),'duration_known'=>''!==trim((string)($c['duration_label']??'')),'language'=>self::clean($c['language']??'',100),'prerequisites'=>self::clean_area($c['prerequisites']??'',600),'prerequisites_known'=>''!==trim((string)($c['prerequisites']??'')),'pace'=>self::clean($c['pace']??'',100),'credential'=>self::clean_area($c['credential']??'',600),'pathways'=>$cp,'my_learning_state'=>sanitize_key((string)($learning[$id]??'')),'score'=>$score,'rank_reasons'=>$reasons,'provider_current_terms_authoritative'=>true);
        }
        usort($ranked,static function($a,$b){$s=absint($b['score']??0)<=>absint($a['score']??0);if($s)return $s;$st=absint($a['stage_rank']??40)<=>absint($b['stage_rank']??40);return $st?:strcmp((string)($a['course_id']??''),(string)($b['course_id']??''));});$selected=array_slice($ranked,0,$limit);usort($selected,static function($a,$b){$st=absint($a['stage_rank']??40)<=>absint($b['stage_rank']??40);if($st)return $st;$s=absint($b['score']??0)<=>absint($a['score']??0);return $s?:strcmp((string)($a['course_id']??''),(string)($b['course_id']??''));});foreach($selected as $i=>&$c){$c['sequence']=$i+1;unset($c['stage_rank']);}unset($c);
        return array('schema'=>self::SCHEMA,'generated_at'=>self::now(),'catalog_verified_on'=>self::catalog_verified_on(),'query'=>array('topic'=>$topic,'goal'=>$goal,'pathway'=>$pathway,'access'=>$access,'limit'=>$limit),'courses'=>$selected,'candidate_count'=>count($ranked),'sequencing_basis'=>'declared-level-label-then-match-score','missing_prerequisites_mean'=>'not-recorded-not-none','missing_duration_mean'=>'not-recorded-not-zero','provider_terms_authoritative'=>true,'saved_route_is_not_enrollment'=>true,'automatic_completion'=>false);
    }

    private static function routes_for_user($uid){$uid=absint($uid);if(!$uid)return array();$r=get_user_meta($uid,self::USER_META,true);$r=is_array($r)?array_values(array_filter($r,'is_array')):array();return array_slice($r,-self::MAX_ROUTES);}
