    private static function context_is_valid($uid,$project_id,$bundle_id,$notebook_id){$project_id=absint($project_id);$notebook_id=absint($notebook_id);$bundle_id=self::clean($bundle_id,100);if($project_id){if(!class_exists('SC_Library_Unified_Research_Projects_Source_Bundles')||!SC_Library_Unified_Research_Projects_Source_Bundles::user_owns_project($project_id,$uid))return false;if($bundle_id){$found=false;foreach(SC_Library_Unified_Research_Projects_Source_Bundles::bundles_for_project($project_id) as $b){if($bundle_id===(string)($b['bundle_id']??'')){$found=true;break;}}if(!$found)return false;}}elseif($bundle_id)return false;if($notebook_id){if(!class_exists('SC_Library_Reading_Notebook_Annotations')||!SC_Library_Reading_Notebook_Annotations::user_owns_notebook($notebook_id,$uid))return false;}return true;}
    private static function checksum($p){return hash('sha256',wp_json_encode($p,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE));}
    private static function sanitize_course_ids($ids){$idx=self::course_index();if(is_string($ids))$ids=preg_split('/[\s,]+/',$ids);$out=array();foreach((array)$ids as $id){$id=sanitize_key((string)$id);if($id&&isset($idx[$id])&&!in_array($id,$out,true))$out[]=$id;if(count($out)>=self::MAX_COURSES_PER_ROUTE)break;}return $out;}
    public static function route_manifest($route,$uid){if(!is_array($route))return array();$idx=self::course_index();$learning=self::course_plan($uid);$courses=array();foreach((array)($route['course_ids']??array()) as $id){$id=sanitize_key((string)$id);if(!isset($idx[$id]))continue;$c=$idx[$id];$courses[]=array('course_id'=>$id,'title'=>self::clean($c['title']??'',240),'institution'=>self::clean($c['institution']??'',160),'url'=>esc_url_raw((string)($c['url']??'')),'level'=>self::clean($c['level']??'',80),'access'=>sanitize_key((string)($c['access']??'')),'access_label'=>self::clean($c['access_label']??'',100),'my_learning_state'=>sanitize_key((string)($learning[$id]??'')));}$p=array('schema'=>self::MANIFEST_SCHEMA,'route_id'=>self::clean($route['route_id']??'',80),'route_urn'=>self::clean($route['route_urn']??'',120),'title'=>self::clean($route['title']??'',200),'goal'=>self::clean_area($route['goal']??'',1200),'pathway'=>sanitize_key((string)($route['pathway']??'')),'access_preference'=>sanitize_key((string)($route['access_preference']??'open-first')),'status'=>sanitize_key((string)($route['status']??'planned')),'project_id'=>absint($route['project_id']??0),'bundle_id'=>self::clean($route['bundle_id']??'',100),'notebook_id'=>absint($route['notebook_id']??0),'course_ids'=>array_values(array_map('sanitize_key',(array)($route['course_ids']??array()))),'courses'=>$courses,'catalog_verified_on'=>self::catalog_verified_on(),'created_at'=>self::clean($route['created_at']??'',60),'updated_at'=>self::clean($route['updated_at']??'',60),'references_only'=>true,'provider_terms_authoritative'=>true,'automatic_enrollment'=>false,'automatic_completion'=>false,'automatic_workspace_write'=>false);$p['manifest_sha256']=self::checksum($p);return $p;}
    public static function save_route($uid,$data){$uid=absint($uid);if(!$uid)return new WP_Error('sc_learning_auth','Sign in to save a learning route.',array('status'=>401));$ids=self::sanitize_course_ids($data['course_ids']??array());if(!$ids)return new WP_Error('sc_learning_courses','Choose at least one listed course.',array('status'=>400));$project=absint($data['project_id']??0);$bundle=self::clean($data['bundle_id']??'',100);$notebook=absint($data['notebook_id']??0);if(!self::context_is_valid($uid,$project,$bundle,$notebook))return new WP_Error('sc_learning_context','The selected research context is not available to this account.',array('status'=>403));$pathways=self::pathways();$path=sanitize_key((string)($data['pathway']??''));if($path&&!isset($pathways[$path]))$path='';$access=sanitize_key((string)($data['access_preference']??'open-first'));if(!isset(self::ACCESS_PREFERENCES[$access]))$access='open-first';$status=sanitize_key((string)($data['status']??'planned'));if(!isset(self::ROUTE_STATUSES[$status]))$status='planned';$uuid=self::new_uuid();$r=array('route_id'=>'learning-route-'.$uuid,'route_urn'=>'urn:sc:learning-route:'.$uuid,'title'=>self::clean($data['title']??'Learning route',200),'goal'=>self::clean_area($data['goal']??'',1200),'pathway'=>$path,'access_preference'=>$access,'status'=>$status,'course_ids'=>$ids,'project_id'=>$project,'bundle_id'=>$bundle,'notebook_id'=>$notebook,'notes'=>self::clean_area($data['notes']??'',3000),'created_at'=>self::now(),'updated_at'=>self::now());$routes=self::routes_for_user($uid);$routes[]=$r;self::write_routes($uid,$routes);return self::route_manifest($r,$uid);}
