    public function register_rest_routes(){
        register_rest_route(self::REST_NAMESPACE,self::REST_ROUTE,array('methods'=>WP_REST_Server::READABLE,'permission_callback'=>'__return_true','callback'=>array($this,'rest_plan')));
        register_rest_route(self::REST_NAMESPACE,self::REST_ROUTE.'/routes',array(array('methods'=>WP_REST_Server::READABLE,'permission_callback'=>array($this,'rest_signed_in'),'callback'=>array($this,'rest_routes')),array('methods'=>WP_REST_Server::CREATABLE,'permission_callback'=>array($this,'rest_signed_in'),'callback'=>array($this,'rest_save_route'))));
        register_rest_route(self::REST_NAMESPACE,self::REST_ROUTE.'/routes/(?P<id>[a-zA-Z0-9-]+)',array('methods'=>WP_REST_Server::DELETABLE,'permission_callback'=>array($this,'rest_signed_in'),'callback'=>array($this,'rest_delete_route')));
