    public function rest_signed_in(){return is_user_logged_in();}
    public function rest_plan(WP_REST_Request $r){return rest_ensure_response(self::build_plan(array('topic'=>$r->get_param('topic')?:$r->get_param('q'),'goal'=>$r->get_param('goal'),'pathway'=>$r->get_param('pathway'),'access'=>$r->get_param('access'),'limit'=>$r->get_param('limit')),get_current_user_id()));}
